/** Whole-interface palettes in styles/palettes (generated by scripts/gen-palettes.mjs). `default` is the core look and needs no attribute. */
export const THEME_PALETTES = ['default', 'graphite', 'saffron', 'glacier', 'nocturne', 'harbor'] as const
export type ThemePalette = (typeof THEME_PALETTES)[number]
/** The VS Code theme each palette adapts, for credits in pickers and docs. */
export const PALETTE_SOURCES: Record<Exclude<ThemePalette, 'default'>, string> = {
  'graphite': 'GitHub Theme',
  'saffron': 'Ayu',
  'glacier': 'Winter is Coming',
  'nocturne': 'Night Owl',
  'harbor': 'Tokyo Night'
}
